% USING_NPC_MODULATOR = true;

%% Controller Options
% Incremental commissioning level. 1: V/f voltage open loop; 2: current loop with synthetic electrical angle; 3: current loop with encoder angle; 4: speed loop with encoder feedback.
% Options: (1), (2), (3), (4), (5), (6)
BUILD_LEVEL = 2;

%% Requirement bindings
% Enable the seven ADC slots used by the PMSM SIL input ABI.
GMP_PIL_RX_MASK = 127;

% Enable three PWM slots and six monitor slots used by the PMSM SIL output ABI.
GMP_PIL_TX_MASK = 4128775;

% Main motor-control ISR frequency in hertz.
CONTROLLER_FREQUENCY = 20e3;

% Minimum absolute phase current in amperes before PWM dead-time compensation selects a current direction. Converted to PU with CTRL_CURRENT_BASE at initialization.
MCS_PWM_DEADTIME_COMP_CURRENT_DEADBAND_A = 0.2;

% Phase-current hysteresis band in amperes used to prevent dead-time compensation direction chatter around zero current.
MCS_PWM_DEADTIME_COMP_CURRENT_HYSTERESIS_A = 0.05;

% Cutoff frequency in hertz of the low-pass filter applied to encoder-derived mechanical speed.
MCS_ENCODER_SPEED_FILTER_FC_HZ = 20.0;

% Position-loop proportional gain. Input is mechanical position error in PU revolutions and output is speed reference in PU, so the gain is speed_pu/position_pu.
MCS_MECH_POSITION_KP_PU = 5.0;

% Position-loop integral gain in speed_pu/(position_pu*s). The continuous gain is divided by the mechanical-loop sampling frequency internally.
MCS_MECH_POSITION_KI_PU_S = 1.0;

% Velocity-loop proportional gain. Input is speed error in PU and output is q-axis current/torque reference in PU, so the gain is current_pu/speed_pu.
MCS_MECH_VELOCITY_KP_PU = 5.0;

% Velocity-loop integral gain in current_pu/(speed_pu*s). The continuous gain is divided by the mechanical-loop sampling frequency internally.
MCS_MECH_VELOCITY_KI_PU_S = 1.0;

% D-axis current reference in amperes used by BUILD_LEVEL 2 and 3 commissioning. Converted to PU using CTRL_CURRENT_BASE.
MCS_COMMISSIONING_ID_REF_A = 1.0;

% Q-axis current reference in amperes used by BUILD_LEVEL 2 and 3 commissioning. Converted to PU using CTRL_CURRENT_BASE.
MCS_COMMISSIONING_IQ_REF_A = 1.0;

% Mechanical speed reference in rpm used by BUILD_LEVEL 4 commissioning. Converted to PU using MOTOR_PARAM_MAX_SPEED.
MCS_COMMISSIONING_SPEED_REF_RPM = 300.0;

% Absolute mechanical speed-command limit in rpm. It is divided by MOTOR_PARAM_MAX_SPEED to obtain the controller PU limit.
MCS_MECH_SPEED_LIMIT_RPM = 3000.0;

% Maximum mechanical speed-command slew rate in rpm/s. The configured value corresponds to 1 PU/s for the selected 3000 rpm motor.
MCS_MECH_SPEED_SLOPE_RPM_S = 3000.0;

% Absolute q-axis current/torque command limit in amperes. It is divided by CTRL_CURRENT_BASE to obtain the controller PU limit; 3 A corresponds to the previous 0.3 PU setting.
MCS_MECH_CURRENT_LIMIT_A = 3.0;

% Rectangular saturation limit for d/q axes in V.
MCS_MAX_RECT_SATURATION_VOLTAGE_V = 10.0;

MCS_MAX_DC_BUS_VOLTAGE_V = CTRL_DCBUS_VOLTAGE*1.2;

MCS_MIN_DC_BUS_VOLTAGE_V = CTRL_DCBUS_VOLTAGE*0.2;

MOTOR_PARAM_INERTIA = 'SM060R20B30MNAD_INERTIA';

MOTOR_PARAM_FLUX = 'SM060R20B30MNAD_FLUX';

MOTOR_PARAM_LD = 'SM060R20B30MNAD_LD';

MOTOR_PARAM_RS = 'SM060R20B30MNAD_RS';

MOTOR_PARAM_LQ = 'SM060R20B30MNAD_LQ';

MOTOR_PARAM_LS = 'SM060R20B30MNAD_LD';

MOTOR_PARAM_FRICTION = 'SM060R20B30MNAD_FRICTION';

MOTOR_PARAM_POLE_PAIRS = 'SM060R20B30MNAD_POLE_PAIRS';

% Controller startup delay in milliseconds.
CTRL_STARTUP_DELAY = 100;

% Minimum delay in milliseconds before the CiA402 state machine enters Operation Enabled. The project control tick is expressed in milliseconds.
MCS_CIA402_OPERATION_ENABLE_DELAY_MS = 100;

% Cutoff frequency in hertz of the second-order low-pass filter used while estimating ADC zero offsets.
MCS_ADC_CALIBRATOR_FC_HZ = 20.0;

% Quality factor of the ADC calibration low-pass filter; 0.707 gives an approximately Butterworth second-order response.
MCS_ADC_CALIBRATOR_Q = 0.707;

% Enable the target ADC-calibration preparation handshake.
MCS_PMSM_ID_ENABLE_PREPARE = 1;

% Enable stator-resistance and inverter dead-time voltage identification.
MCS_PMSM_ID_ENABLE_RS_DT = 1;

% Enable d/q-axis inductance pulse identification.
MCS_PMSM_ID_ENABLE_LDQ = 1;

% Enable PM flux-linkage identification.
MCS_PMSM_ID_ENABLE_FLUX = 1;

% Maximum closed-loop current in amperes used by the Rs/dead-time sweep.
MCS_PMSM_ID_RSDT_MAX_CURRENT_A = 5.0;

% Minimum closed-loop current in amperes used by the Rs/dead-time sweep.
MCS_PMSM_ID_RSDT_MIN_CURRENT_A = 1.0;

% Number of positive current points in the Rs/dead-time regression.
MCS_PMSM_ID_RSDT_STEPS = 5;

% Rotor alignment dwell in seconds before the Rs/dead-time sweep.
MCS_PMSM_ID_RSDT_ALIGN_TIME_S = 1.0;

% Settling delay in seconds after changing each Rs/dead-time current point.
MCS_PMSM_ID_RSDT_MEASURE_DELAY_S = 0.2;

% Number of ISR samples averaged at each Rs/dead-time current point.
MCS_PMSM_ID_RSDT_MEASURE_POINTS = 100;

% Physical d/q pulse voltage in volts used for inductance identification.
MCS_PMSM_ID_LDQ_PULSE_VOLTAGE_V = 0.277128;

% Maximum current bias in amperes used for the inductance profile.
MCS_PMSM_ID_LDQ_MAX_BIAS_CURRENT_A = 5.0;

% Number of bias points recorded for each inductance axis.
MCS_PMSM_ID_LDQ_BIAS_STEPS = 12;

% D-axis alignment current in amperes used before inductance pulses.
MCS_PMSM_ID_LDQ_ALIGN_CURRENT_A = 5.0;

% Bias-current settling time in seconds before each inductance pulse.
MCS_PMSM_ID_LDQ_SETTLE_TIME_S = 0.2;

% Inductance voltage-pulse duration in seconds.
MCS_PMSM_ID_LDQ_PULSE_TIME_S = 0.002;

% Zero-voltage cooldown time in seconds between inductance pulses.
MCS_PMSM_ID_LDQ_COOLDOWN_TIME_S = 0.05;

% Minimum mechanical speed in rpm used by the flux-linkage regression.
MCS_PMSM_ID_FLUX_MIN_SPEED_RPM = 300.0;

% Maximum mechanical speed in rpm used by the flux-linkage regression.
MCS_PMSM_ID_FLUX_MAX_SPEED_RPM = 1800.0;

% Number of speed points used by the flux-linkage regression.
MCS_PMSM_ID_FLUX_STEPS = 6;

% Current magnitude in amperes used for I/F flux-linkage rotation.
MCS_PMSM_ID_FLUX_IF_CURRENT_A = 4.0;

% Settling time in seconds at each flux-identification speed.
MCS_PMSM_ID_FLUX_SETTLE_TIME_S = 2.0;

% Number of ISR samples averaged at each flux-identification speed.
MCS_PMSM_ID_FLUX_MEASURE_POINTS = 2000;

% Enable sensored phase-A alignment, pole-pair detection and encoder-offset calibration before electrical/mechanical identification.
MCS_PMSM_ID_ENABLE_ENCODER_CALIBRATION = 1;

% Enable the sensored constant-Iq acceleration and PWM-off coast-down mechanical identification stage.
MCS_PMSM_ID_ENABLE_MECHANICAL_ID = 1;

% Closed-loop d-axis current in amperes used to lock the rotor to phase A during encoder calibration.
MCS_PMSM_ID_ENCODER_ALIGN_CURRENT_A = 1.0;

% PWM-off observation time in seconds used to detect a randomly jumping encoder.
MCS_PMSM_ID_ENCODER_NOISE_CHECK_TIME_S = 0.10;

% Time in seconds allowed for the rotor to settle at the phase-A electrical zero.
MCS_PMSM_ID_ENCODER_ALIGN_SETTLE_TIME_S = 0.30;

% Electrical revolutions per second used while rotating the alignment current vector.
MCS_PMSM_ID_ENCODER_SWEEP_ELEC_HZ = 1.0;

% Dwell time in seconds at phase A after each complete electrical revolution.
MCS_PMSM_ID_ENCODER_ANCHOR_SETTLE_TIME_S = 0.10;

% Maximum wrapped mechanical-position change accepted in one control ISR sample.
MCS_PMSM_ID_ENCODER_MAX_SAMPLE_JUMP_PU = 0.02;

% Maximum unwrapped position span accepted during the PWM-off encoder noise test.
MCS_PMSM_ID_ENCODER_MAX_STATIONARY_SPAN_PU = 0.002;

% Minimum net mechanical motion required during one electrical revolution; below this reports an uncoupled/stuck encoder.
MCS_PMSM_ID_ENCODER_MIN_CYCLE_MOTION_PU = 0.02;

% Maximum absolute deviation of each electrical-cycle mechanical motion from the measured mean.
MCS_PMSM_ID_ENCODER_MAX_CYCLE_DEVIATION_PU = 0.03;

% Maximum wrapped mechanical-position error accepted when returning to the first phase-A anchor.
MCS_PMSM_ID_ENCODER_ZERO_RETURN_TOLERANCE_PU = 0.02;

% Maximum pole-pair count searched before encoder calibration stops with a zero-return fault.
MCS_PMSM_ID_ENCODER_MAX_POLE_PAIRS = 16;

% User-selected mechanical target speed in rpm for the identification test.
MCS_PMSM_ID_MECH_TARGET_SPEED_RPM = 1000.0;

% User-selected q-axis current in amperes applied by the real current loop during acceleration.
MCS_PMSM_ID_MECH_ACCEL_CURRENT_A = 1.0;

% Lower acceleration/coast fitting boundary relative to the selected target speed.
MCS_PMSM_ID_MECH_FIT_LOW_RATIO = 0.30;

% Upper acceleration/coast fitting boundary relative to the selected target speed.
MCS_PMSM_ID_MECH_FIT_HIGH_RATIO = 0.70;

% Target-speed ratio at which PWM is physically disabled to start free coast-down.
MCS_PMSM_ID_MECH_PWM_OFF_RATIO = 0.75;

% Safety timeout in seconds covering acceleration and free coast-down.
MCS_PMSM_ID_MECH_MAX_TEST_TIME_S = 20.0;

% Expected maximum combined duration of the two recorded 30%-70% speed curves.
MCS_PMSM_ID_MECH_RECORD_TIME_S = 10.0;

% Minimum coefficient of determination accepted for acceleration-versus-speed regression.
MCS_PMSM_ID_MECH_MIN_FIT_R2 = 0.80;

% Minimum differentiated samples required in each acceleration and coast curve.
MCS_PMSM_ID_MECH_MIN_FIT_SAMPLES = 30;

